-- Example texts of each text layer: shown in a layout until the manager's own words fill it.
alter table public.motion_templates add column sample jsonb not null default '{}'::jsonb;
update public.motion_templates set sample = '{"tag": "Nouveau", "title": "Ouvert le dimanche", "text": "Dès ce week-end, de 10h à 13h, tout le mois de décembre."}'::jsonb where id = '5d6f0a1e-0c1b-4c8e-9a01-000000000008';
update public.motion_templates set sample = '{"left": "Avant", "right": "Après", "caption": "Balayage miel et coupe dégradée, 2 h 30 de soin."}'::jsonb where id = '5d6f0a1e-0c1b-4c8e-9a01-000000000009';
update public.motion_templates set sample = '{"title": "Avant votre rendez-vous", "items": "Arrivez 5 minutes avant | Pour prendre le temps de vous installer.\nVenez cheveux secs | Le diagnostic est plus précis.\nApportez une photo | De la coupe ou de la couleur qui vous inspire.\nPrévenez-nous en cas d''empêchement | 24 h avant, pour libérer le créneau."}'::jsonb where id = '5d6f0a1e-0c1b-4c8e-9a01-000000000001';
update public.motion_templates set sample = '{"kicker": "Nouveauté", "title": "La collection d''automne est là", "subtitle": "Glisse pour tout voir →"}'::jsonb where id = '5d6f0a1e-0c1b-4c8e-9a01-000000000002';
update public.motion_templates set sample = '{"number": "10", "label": "ans ce mois-ci", "caption": "Merci à vous ! Une surprise vous attend en boutique toute la semaine."}'::jsonb where id = '5d6f0a1e-0c1b-4c8e-9a01-000000000007';
update public.motion_templates set sample = '{"badge": "-20 %", "badge_note": "jusqu''à dimanche", "title": "Le menu du midi", "detail": "Entrée, plat et dessert, du mardi au vendredi.", "cta": "Réservez en bio"}'::jsonb where id = '5d6f0a1e-0c1b-4c8e-9a01-000000000003';
update public.motion_templates set sample = '{"title": "Nos horaires", "rows": "Mar | 9h – 19h | Sur rendez-vous\nMer | 9h – 19h | Sans rendez-vous\nJeu | 10h – 20h | Nocturne\nVen | 9h – 19h | \nSam | 9h – 17h | ", "note": "Réservation en ligne, lien en bio"}'::jsonb where id = '5d6f0a1e-0c1b-4c8e-9a01-000000000004';
update public.motion_templates set sample = '{"quote": "Le meilleur accueil du quartier, on s''y sent comme à la maison.", "author": "Camille, cliente depuis 2 ans"}'::jsonb where id = '5d6f0a1e-0c1b-4c8e-9a01-000000000005';
update public.motion_templates set sample = '{"title": "Comment commander", "steps": "Choisissez | Sur notre site ou en boutique.\nOn prépare | Votre commande est prête en 2 h.\nVous récupérez | Ou on vous livre dans le quartier."}'::jsonb where id = '5d6f0a1e-0c1b-4c8e-9a01-000000000006';
